import { clsx, type ClassValue } from "clsx"
import { extendTailwindMerge, twMerge } from "tailwind-merge"

// The shell writes its Tailwind classes with the `uhuu:` prefix (styles/uhuu-editor-theme.css), so
// conflicts are resolved between prefixed classes; any unprefixed class passes through untouched.
const twMergeShell = extendTailwindMerge({ prefix: "uhuu" })

export function cn(...inputs: ClassValue[]) {
  return twMergeShell(clsx(inputs))
}

// Page output (ImageBlock) merges its defaults with a template's own, unprefixed classes, so a
// template's `object-contain` or `object-[30%_20%]` still replaces the default `object-cover`.
export function cnPage(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
