/** Shared page-list rules. No React or DOM; callers own state. */
import { errorOnce, warnOnce } from '../../utility/diagnostics';

type PositionedItem = { id: string; strictPosition?: unknown };
type InsertPosition = { mode: 'end' } | { mode: 'before' | 'after'; anchorId: string };
type KeyIssue = { reason: 'invalid-result' | 'invalid-keys' | 'evaluation-error'; detail: unknown };

export function resolvePageComponentKeys<Context>(
  keys: string[] | ((context: Context) => string[]) | undefined,
  context: Context,
): { keys: string[]; issue?: KeyIssue } {
  if (!keys) return { keys: [] };
  if (Array.isArray(keys)) return { keys };
  try {
    const result = keys(context);
    if (!Array.isArray(result)) return { keys: [], issue: { reason: 'invalid-result', detail: typeof result } };
    const filtered = result.filter((key) => typeof key === 'string');
    return filtered.length === result.length ? { keys: filtered } : { keys: filtered, issue: { reason: 'invalid-keys', detail: result } };
  } catch (error) {
    return { keys: [], issue: { reason: 'evaluation-error', detail: error } };
  }
}

/** Kept outside the pure resolver so every shell path reports the same invalid template input. */
export function evaluatePageComponentKeys<Context>(
  keys: string[] | ((context: Context) => string[]) | undefined,
  context: Context,
  groupId?: string,
): string[] {
  const result = resolvePageComponentKeys(keys, context);
  reportPageComponentKeysIssue(result.issue, groupId);
  return result.keys;
}

/** Once per group and mistake: keys are evaluated on every payload change and dialog render. */
export function reportPageComponentKeysIssue(issue?: KeyIssue, groupId?: string): void {
  if (!issue) return;
  const group = groupId ? `page group "${groupId}"` : 'a page group';
  const key = `pageComponentKeys:${groupId ?? ''}:${issue.reason}:${String(issue.detail)}`;
  if (issue.reason === 'invalid-keys') {
    warnOnce(key, `[uhuu-components] pageComponentKeys of ${group} returned non-string values; they are left out.`, issue.detail);
  } else if (issue.reason === 'invalid-result') {
    errorOnce(key, `[uhuu-components] pageComponentKeys of ${group} must return an array of page keys, got ${String(issue.detail)}; the group renders no pages.`);
  } else {
    errorOnce(key, `[uhuu-components] pageComponentKeys of ${group} threw; the group renders no pages:`, issue.detail);
  }
}

export function partitionPageItems<Item extends PositionedItem>(items: readonly Item[]) {
  const start: Item[] = [];
  const middle: Item[] = [];
  const end: Item[] = [];
  for (const item of items) {
    if (item.strictPosition === 'start') start.push(item);
    else if (item.strictPosition === 'end') end.push(item);
    else middle.push(item);
  }
  return { start, middle, end };
}

export function enforcePageItemPositions<Item extends PositionedItem>(items: readonly Item[]): Item[] {
  const { start, middle, end } = partitionPageItems(items);
  return [...start, ...middle, ...end];
}

export function insertPageItem<Item extends PositionedItem>(items: readonly Item[], item: Item, position?: InsertPosition): Item[] {
  if (item.strictPosition === 'start') return [item, ...items];
  if (item.strictPosition === 'end') return [...items, item];
  const { start, middle, end } = partitionPageItems(items);
  let index = middle.length;
  if (position && position.mode !== 'end') {
    const anchor = middle.findIndex((entry) => entry.id === position.anchorId);
    if (anchor !== -1) index = anchor + (position.mode === 'after' ? 1 : 0);
    else if (items.find((entry) => entry.id === position.anchorId)?.strictPosition === 'start') index = 0;
  }
  return [...start, ...middle.slice(0, index), item, ...middle.slice(index), ...end];
}
